#!/usr/bin/env python3
"""
PDDL solver for grounded airport domain problems.
Uses BFS forward state-space search.
"""

import re
import json
from collections import deque

def parse_pddl_file(filepath):
    """Read and return the content of a PDDL file."""
    with open(filepath, 'r') as f:
        return f.read()

def tokenize(text):
    """Tokenize PDDL text into a list of tokens."""
    # Remove comments
    text = re.sub(r';[^\n]*', '', text)
    # Add spaces around parens
    text = text.replace('(', ' ( ').replace(')', ' ) ')
    return text.split()

def parse_sexp(tokens, idx=0):
    """Parse S-expression from tokens starting at idx. Returns (sexp, next_idx)."""
    if tokens[idx] == '(':
        lst = []
        idx += 1
        while tokens[idx] != ')':
            elem, idx = parse_sexp(tokens, idx)
            lst.append(elem)
        return lst, idx + 1
    else:
        return tokens[idx], idx + 1

def parse_all_sexps(text):
    """Parse all top-level S-expressions from text."""
    tokens = tokenize(text)
    results = []
    idx = 0
    while idx < len(tokens):
        if tokens[idx] == '(':
            sexp, idx = parse_sexp(tokens, idx)
            results.append(sexp)
        else:
            idx += 1
    return results

def extract_actions(domain_sexp):
    """Extract action definitions from domain s-expression."""
    actions = []
    for item in domain_sexp:
        if isinstance(item, list) and len(item) > 0 and isinstance(item[0], str) and item[0] == ':action':
            action_name = item[1]
            params = []
            precondition = None
            effect = None
            i = 2
            while i < len(item):
                if item[i] == ':parameters':
                    params = item[i+1]
                    i += 2
                elif item[i] == ':precondition':
                    precondition = item[i+1]
                    i += 2
                elif item[i] == ':effect':
                    effect = item[i+1]
                    i += 2
                else:
                    i += 1
            actions.append({
                'name': action_name,
                'parameters': params,
                'precondition': precondition,
                'effect': effect
            })
    return actions

def extract_constants(domain_sexp):
    """Extract constants and their types from domain."""
    constants = {}
    for item in domain_sexp:
        if isinstance(item, list) and len(item) > 0 and item[0] == ':constants':
            # Parse typed list: obj1 obj2 ... - type obj3 ... - type2
            i = 1
            current_names = []
            while i < len(item):
                if item[i] == '-':
                    type_name = item[i+1]
                    for name in current_names:
                        constants[name] = type_name
                    current_names = []
                    i += 2
                else:
                    current_names.append(item[i])
                    i += 1
    return constants

def flatten_facts(sexp, substitution=None):
    """
    Extract a list of (positive, fact_tuple) from a precondition or effect.
    positive=True means the fact must hold / is added.
    positive=False means (not (fact)) - must not hold / is deleted.
    """
    if substitution is None:
        substitution = {}

    results = []
    if not isinstance(sexp, list) or len(sexp) == 0:
        return results

    if sexp[0] == 'and':
        for sub in sexp[1:]:
            results.extend(flatten_facts(sub, substitution))
    elif sexp[0] == 'not':
        inner = sexp[1]
        # inner should be a predicate
        fact = tuple(substitution.get(x, x) for x in inner)
        results.append((False, fact))
    else:
        # It's a predicate
        fact = tuple(substitution.get(x, x) for x in sexp)
        results.append((True, fact))

    return results

def get_param_names(params_list):
    """Extract parameter variable names from parameter list."""
    names = []
    for p in params_list:
        if isinstance(p, str) and p.startswith('?'):
            names.append(p)
        elif isinstance(p, list):
            for pp in p:
                if isinstance(pp, str) and pp.startswith('?'):
                    names.append(pp)
    return names

def extract_init_and_goal(problem_sexp):
    """Extract initial state facts and goal facts from problem s-expression."""
    init_facts = set()
    goal_facts = []

    for item in problem_sexp:
        if isinstance(item, list) and len(item) > 0:
            if item[0] == ':init':
                for fact in item[1:]:
                    if isinstance(fact, list):
                        init_facts.add(tuple(fact))
            elif item[0] == ':goal':
                goal_sexp = item[1]
                if isinstance(goal_sexp, list) and goal_sexp[0] == 'and':
                    for fact in goal_sexp[1:]:
                        if isinstance(fact, list):
                            goal_facts.append(tuple(fact))
                elif isinstance(goal_sexp, list):
                    goal_facts.append(tuple(goal_sexp))

    return init_facts, goal_facts

def ground_actions(actions, constants):
    """Ground actions by substituting parameters with constants of matching type."""
    grounded = []

    for action in actions:
        param_names = get_param_names(action['parameters'])

        if len(param_names) == 0:
            # Already grounded
            precond_facts = flatten_facts(action['precondition'])
            effect_facts = flatten_facts(action['effect'])
            grounded.append({
                'name': action['name'],
                'args': [],
                'preconditions_pos': [f for (pos, f) in precond_facts if pos],
                'preconditions_neg': [f for (pos, f) in precond_facts if not pos],
                'effects_add': [f for (pos, f) in effect_facts if pos],
                'effects_del': [f for (pos, f) in effect_facts if not pos],
            })
        elif len(param_names) == 1:
            # Find the type constraint from preconditions or parameters
            # Get parameter types from parameter list
            param_types = {}
            params = action['parameters']
            if isinstance(params, list):
                i = 0
                current_vars = []
                while i < len(params):
                    if isinstance(params[i], str):
                        if params[i] == '-':
                            type_name = params[i+1]
                            for v in current_vars:
                                param_types[v] = type_name
                            current_vars = []
                            i += 2
                        elif params[i].startswith('?'):
                            current_vars.append(params[i])
                            i += 1
                        else:
                            i += 1
                    elif isinstance(params[i], list):
                        # Nested like (?a - airplane)
                        sub = params[i]
                        j = 0
                        sub_vars = []
                        while j < len(sub):
                            if isinstance(sub[j], str):
                                if sub[j] == '-':
                                    for v in sub_vars:
                                        param_types[v] = sub[j+1]
                                    sub_vars = []
                                    j += 2
                                elif sub[j].startswith('?'):
                                    sub_vars.append(sub[j])
                                    j += 1
                                else:
                                    j += 1
                            else:
                                j += 1
                        i += 1
                    else:
                        i += 1

            var_name = param_names[0]
            var_type = param_types.get(var_name)

            # Get all constants of the matching type
            matching_consts = [c for c, t in constants.items() if t == var_type] if var_type else list(constants.keys())

            for const in matching_consts:
                sub = {var_name: const}
                precond_facts = flatten_facts(action['precondition'], sub)
                effect_facts = flatten_facts(action['effect'], sub)
                grounded.append({
                    'name': action['name'],
                    'args': [const],
                    'preconditions_pos': [f for (pos, f) in precond_facts if pos],
                    'preconditions_neg': [f for (pos, f) in precond_facts if not pos],
                    'effects_add': [f for (pos, f) in effect_facts if pos],
                    'effects_del': [f for (pos, f) in effect_facts if not pos],
                })

    return grounded

def is_applicable(action, state):
    """Check if action is applicable in state."""
    for fact in action['preconditions_pos']:
        if fact not in state:
            return False
    for fact in action['preconditions_neg']:
        if fact in state:
            return False
    return True

def apply_action(action, state):
    """Apply action to state and return new state."""
    new_state = set(state)
    for fact in action['effects_del']:
        new_state.discard(fact)
    for fact in action['effects_add']:
        new_state.add(fact)
    return frozenset(new_state)

def check_goal(state, goal_facts):
    """Check if all goal facts are satisfied in state."""
    for fact in goal_facts:
        if fact not in state:
            return False
    return True

def solve(domain_file, problem_file):
    """Solve a PDDL planning problem using BFS."""
    domain_text = parse_pddl_file(domain_file)
    problem_text = parse_pddl_file(problem_file)

    domain_sexps = parse_all_sexps(domain_text)
    problem_sexps = parse_all_sexps(problem_text)

    # Find the define expressions
    domain_sexp = None
    problem_sexp = None
    for s in domain_sexps:
        if isinstance(s, list) and s[0] == 'define':
            domain_sexp = s
            break
    for s in problem_sexps:
        if isinstance(s, list) and s[0] == 'define':
            problem_sexp = s
            break

    # Extract components
    constants = extract_constants(domain_sexp)
    actions = extract_actions(domain_sexp)
    init_facts, goal_facts = extract_init_and_goal(problem_sexp)

    # Also extract constants from problem (objects section)
    for item in problem_sexp:
        if isinstance(item, list) and len(item) > 0 and item[0] == ':objects':
            i = 1
            current_names = []
            while i < len(item):
                if item[i] == '-':
                    type_name = item[i+1]
                    for name in current_names:
                        constants[name] = type_name
                    current_names = []
                    i += 2
                else:
                    current_names.append(item[i])
                    i += 1

    # Ground actions
    grounded = ground_actions(actions, constants)

    print(f"Constants: {constants}")
    print(f"Number of grounded actions: {len(grounded)}")
    print(f"Initial state size: {len(init_facts)}")
    print(f"Goal facts: {goal_facts}")

    # BFS search
    init_state = frozenset(init_facts)

    if check_goal(init_state, goal_facts):
        return []

    queue = deque()
    queue.append((init_state, []))
    visited = {init_state}

    iterations = 0
    while queue:
        state, plan = queue.popleft()
        iterations += 1

        if iterations % 10000 == 0:
            print(f"Iterations: {iterations}, Queue size: {len(queue)}, Plan length: {len(plan)}")

        for action in grounded:
            if is_applicable(action, state):
                new_state = apply_action(action, state)

                if new_state not in visited:
                    new_plan = plan + [action]

                    if check_goal(new_state, goal_facts):
                        print(f"Solution found after {iterations} iterations, plan length: {len(new_plan)}")
                        return new_plan

                    visited.add(new_state)
                    queue.append((new_state, new_plan))

    print("No solution found!")
    return None

def format_plan(plan):
    """Format plan as PDDL plan string."""
    lines = []
    for action in plan:
        if action['args']:
            line = f"{action['name']}({', '.join(action['args'])})"
        else:
            line = f"{action['name']}()"
        lines.append(line)
    return '\n'.join(lines)

def main():
    with open('problem.json', 'r') as f:
        tasks = json.load(f)

    for task in tasks:
        print(f"\n{'='*60}")
        print(f"Solving task: {task['id']}")
        print(f"{'='*60}")

        plan = solve(task['domain'], task['problem'])

        if plan is not None:
            plan_str = format_plan(plan)
            print(f"\nPlan:\n{plan_str}")

